-- Owner-authorized publication of matched appliances with working approved PIM photos.
-- Guard every description, specification, image, source date, pricing and verification label.
BEGIN;
CREATE TEMP TABLE publish_matched_expected ON COMMIT DROP AS
SELECT * FROM jsonb_to_recordset($proof$[{"id":"8866d86f-7b5d-4057-aa7a-085fc1be7d45","model":"HUI56551UC","pim_id":"ad54534d-674a-4d6c-a683-826d60bbf37b","image":"https://media3.bsh-group.com/Product_Shots/20145158_HUI56551UC_Front_Facing_def.webp"},{"id":"83f50989-c108-40a2-b82a-691360681923","model":"FFSGS6219-48WHT","pim_id":"aee2762f-d4cd-43aa-85dc-431703901901","image":"https://cdn.shopify.com/s/files/1/0762/2580/6579/files/Gas-Range_FFSGS6219-48WHT_Front_2026-09-28.jpg?v=1790661834"},{"id":"6df2b81b-4f64-4e37-a1ec-eea1b91837da","model":"B36FD10ENS","pim_id":"eed341ba-ff07-4493-aaa5-a006577844ac","image":"https://media3.bsh-group.com/Product_Shots/25187285_B36FD10ENS_Bosch-Refrigerator-Side-Angle-Right_STP_def.webp"},{"id":"fcb6b867-eab7-463b-83dd-3fd823273aa8","model":"FFFFD1722-32RSG-WHT","pim_id":"77987418-e437-484a-bb9e-2249c9113783","image":"https://forno.ca/cdn/shop/files/Refrigerator_FFFFD1722-32RSG-WHT_V2_1_Front_Main_Picture_23-04-2025.jpg?v=1764602674&width=1920"},{"id":"d702569c-fbd1-40c6-9e3f-13f6cec2bbcf","model":"B24CB50ESS","pim_id":"dc899c08-3dda-4743-8a99-52afa7455a29","image":"https://media3.bsh-group.com/Product_Shots/22738033_B24CB50ESS-Bosch-Refrigeration-Front-Facing-SS_def.webp"},{"id":"4ca49fbe-55d4-4fb8-b683-92bbfbabb700","model":"SPV68C73UC","pim_id":"f3e6ba73-d1e5-44d2-90ad-f03b5c466780","image":"https://media3.bsh-group.com/Product_Shots/24871222_SPV68C73UC-Bosch-Dish-Front-Facing-SS_def.webp"},{"id":"53a635d6-06d1-44bb-b41c-9c187f7eae98","model":"AK8400BS-ES","pim_id":"e34fa000-34a0-4c90-aaca-8a7229c17d5e","image":"https://zephyronline.com/wp-content/uploads/2023/03/AK84-B-ES-Tornado-Mini-Energy-Start-product-card.jpg"},{"id":"bcb4a93a-4c4c-49c6-9c45-1efb7107d149","model":"B36CT80SNB","pim_id":"bb0ce05e-6b47-475d-abb3-cab63571cefd","image":"https://media3.bsh-group.com/Product_Shots/20145356_B36CT80SNB_Front_Facing_def.webp"},{"id":"5d65c94c-1789-419c-81b4-10093d3ced47","model":"B36CL81ENW","pim_id":"e7841d3d-133d-4bd6-809c-a201ae69feed","image":"https://media3.bsh-group.com/Product_Shots/23051808_B36CL81ENW-Bosch-Refrigeration-Angled-Left_def.webp"},{"id":"0ae2b402-983e-4d7f-bfde-29ebde3086e0","model":"SKSIR360IS","pim_id":"ba302ac4-f3de-40d9-a9c6-14bcb2dd13bb","image":"https://www.sksappliances.com/media/images/SKSIR360IS_36_Inch_Induction_Lif.width-2000.format-webp.webp"},{"id":"a3fa6b34-58ec-4196-9c56-a4defb6d620b","model":"HCP34E52UC","pim_id":"2e3c777e-3304-4044-8b90-e9386b6c0766","image":"https://media3.bsh-group.com/Product_Shots/19725150_HCP34E52UC_v11_Front_Facing_3000x3000_0001_def.webp"},{"id":"79bdd982-889f-451e-b304-b484675bad63","model":"B36CT81ENS","pim_id":"ec3743ab-d9fd-4b05-9edb-025a576e536f","image":"https://media3.bsh-group.com/Product_Shots/17192733_B36CT81ENS_Bosch-Refrigerator-Side-Angle-Right_STP_def.webp"},{"id":"4d8f295c-d302-471d-ab7a-11a8fa3edd85","model":"B30IR905SP","pim_id":"f0b5ecc1-e21f-4a68-b78f-9cbb311bfef4","image":"https://media3.bsh-group.com/Product_Shots/MCSA02433836_i3102_1813543_B30IR900SP_cmyk_def.webp"},{"id":"ccc765a3-ff9d-492d-b0f9-745f55f5625c","model":"SKSDW2402P","pim_id":"dbdad842-912a-4890-805b-fa4c15de60b2","image":"https://www.sksappliances.com/media/images/SKSDW2402P.original.jpg"}]$proof$::jsonb) x(id uuid,model text,pim_id uuid,image text);
CREATE TEMP TABLE publish_matched_before ON COMMIT DROP AS
SELECT e.*,to_jsonb(p) AS product_before FROM publish_matched_expected e
JOIN public.products p ON p.id=e.id JOIN tj.aiq_products t ON t.id=e.pim_id
WHERE p.model_number=e.model AND p.image_url=e.image AND p.status='needs_review'
AND t.status='active' AND t.approval_status='approved' AND tj_private.pim_web_image_appliance(t)
AND greatest(t.created_at,t.updated_at,t.source_extracted_at)<=now()+interval '5 minutes';
DO $check$ BEGIN IF (SELECT count(*) FROM publish_matched_before)<>14 THEN RAISE EXCEPTION 'publication_preconditions_changed'; END IF; END $check$;
UPDATE public.products p SET status='active' FROM publish_matched_before b WHERE p.id=b.id AND p.status='needs_review';
DO $check$ BEGIN IF EXISTS(SELECT 1 FROM publish_matched_before b JOIN public.products p ON p.id=b.id WHERE
(b.product_before-ARRAY['status','updated_at']) IS DISTINCT FROM (to_jsonb(p)-ARRAY['status','updated_at']) OR p.status<>'active') THEN RAISE EXCEPTION 'publication_changed_source_facts'; END IF; END $check$;
COMMIT;
